import { useState, useEffect, Children, isValidElement, cloneElement, useMemo } from "react";
import { useTheme } from "@theme";

import { BarChartProps, YAxisProps, BarProps } from "../chart.types";

export const useBarChart = ({ data: initialData, children }: BarChartProps) => {
  const theme = useTheme();
  const [chartData, setChartData] = useState(initialData);
  const [sortOrder, setSortOrder] = useState<"asc" | "desc" | "none">("none");

  useEffect(() => {
    setChartData(initialData);
  }, [initialData]);

  const derived = useMemo(() => {
    if (!theme) {
      return {
        numCategoricalColors: 0,
        numBars: 0,
        childrenWithProps: children,
        colorMap: {} as Record<string, string>,
      };
    }

    const categoricalColorKeys = Object.keys(theme.color.data.categorical).filter((key) =>
      key.endsWith("Default"),
    );
    const numCategoricalColors = categoricalColorKeys.length;

    const countBars = (children: React.ReactNode): number => {
      return Children.toArray(children).reduce((acc: number, child) => {
        if (isValidElement(child)) {
          if ((child.type as { displayName?: string })?.displayName === "Bar") {
            acc += 1;
          }
        }
        return acc;
      }, 0);
    };

    const numBars = countBars(children);
    let barIndex = 0;
    const colorMap: Record<string, string> = {};

    const childrenWithProps = Children.map(children, (child) => {
      if (
        isValidElement(child) &&
        (child.type as { displayName?: string })?.displayName === "Bar"
      ) {
        const currentBarIndex = barIndex++;
        const { dataKey, name, fill } = child.props as BarProps;

        // Resolved color for this bar index
        const colorKey = `${
          (currentBarIndex % numCategoricalColors) + 1
        }Default` as keyof typeof theme.color.data.categorical;
        const resolvedColor = fill || theme.color.data.categorical[colorKey];

        // Map both dataKey and name to the resolved color for Legend lookup
        if (dataKey) colorMap[String(dataKey)] = resolvedColor;
        if (name) colorMap[String(name)] = resolvedColor;

        return cloneElement(child as React.ReactElement<BarProps>, {
          barIndex: currentBarIndex,
          fill: resolvedColor,
          ...child.props,
        });
      }
      return child;
    });

    return {
      numCategoricalColors,
      numBars,
      childrenWithProps,
      colorMap,
    };
  }, [theme, children]);

  const handleSort = (sortable: YAxisProps["sortable"], dataKey: string | undefined) => {
    const newSortOrder = sortOrder === "asc" ? "desc" : "asc";
    const sortedData = [...(chartData || [])].sort((a, b) => {
      if (typeof sortable === "function") {
        const sorted = sortable(a, b);
        if (newSortOrder === "asc") {
          return sorted;
        } else if (newSortOrder === "desc") {
          return -sorted;
        }
      }
      if (dataKey) {
        if (newSortOrder === "asc") {
          return (a as never)[dataKey] - (b as never)[dataKey];
        }
        return (b as never)[dataKey] - (a as never)[dataKey];
      }
      return 0;
    });
    setChartData(sortedData);
    setSortOrder(newSortOrder);
  };

  return {
    chartData,
    sortOrder,
    handleSort,
    ...derived,
  };
};
